#include <iostream>
#include <cmath>

int main() {
    const long long MOD = 1000000007;
    long long n, k;
    std::cin >> n >> k;
    long long p;
    if (k < 2) {
        p = n - (1 - k);
    } else {
        long long length = 1;
        long long temp = k;
        while (temp != 1) {
            temp = (temp * k) % n;
            length += 1;
        }
        p = (n - 1) / length;
    }
    long long result = 1;
    long long base = n % MOD;
    long long exp = p;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp /= 2;
    }
    std::cout << result << std::endl;
    return 0;
}
